// One webhook call carries one event.
const b = $input.first().json.body ?? $input.first().json;
let url;
try { url = new URL(b.episodeUrl || ''); } catch { return []; }
// Only episodes served by our media origin (host owntube-media.*) — every
// other podcast the account plays flows through PCS hooks too, and none of
// it belongs to OwnTube.
if (url.hostname.split('.')[0] !== 'owntube-media') return [];
const m = url.pathname.match(/\/enclosure\/([A-Za-z0-9_-]{11})\./)
  || url.pathname.match(/\/([A-Za-z0-9_-]{11})(?:\.[A-Za-z0-9]+)?$/);
if (!m) return [];
// OwnTube's history input caps durations at 24h.
const cap = (v) => Math.min(Math.max(Number(v) || 0, 0), 86400);
return [{ json: {
  event: b.event,
  videoId: m[1],
  playedUpTo: cap(b.playedUpTo),
  duration: cap(b.duration),
  episodeTitle: b.episodeTitle || '',
  podcastTitle: b.podcastTitle || '',
} }];

const src = $('Ours only').first().json;
const res = $input.first().json;
const status = res.statusCode ?? 200;
const body = JSON.stringify(res.body ?? res);
// OwnTube does not have this video — nothing to write, and not an error.
if (status === 404 || body.includes('NOT_FOUND')) return [];
// Anything else that isn't a clean answer fails the execution, so the webhook
// answers 500 and PCS retries the event later.
if (status >= 300 || body.includes('"error"')) {
  throw new Error(`video.detail failed (HTTP ${status})`);
}
// video.detail is a public tRPC query; its superjson envelope nests the
// payload, so read the channel id out of the raw response.
const cm = body.match(/"channelId"\s*:\s*"([^"]+)"/);
if (!cm) throw new Error('video.detail returned no channelId');
return [{ json: {
  ...src,
  channelId: cm[1],
  completed: src.event === 'archived' || src.event === 'completed',
} }];

const src = $('Prepare write').first().json;
// tRPC can report a failure inside a 200 envelope.
if (JSON.stringify($input.first().json).includes('"error"')) {
  throw new Error('history.upsertEvent returned an error');
}
// Archiving in Pocket Casts also removes the video from the collection its
// feed was published from; every other event stops here.
return src.event === 'archived' ? [{ json: src }] : [];
